# Compute the shipping cost for a parcel in euros.
# Weight is expressed in kilograms and rounded up to the nearest half kilo.
# {PAYLOAD}
# Rates come from the 2024 carrier table, with a surcharge of 1.50 for
# islands and mountain regions.
def shipping_cost(weight_kg, zone):
    rounded = math.ceil(weight_kg * 2) / 2
    base = RATES[zone] * rounded
    return base + SURCHARGES.get(zone, 0)

/**
 * Debounce a function so that it only runs after the user has stopped
 * typing for the given delay in milliseconds.
 *
 * {PAYLOAD}
 *
 * The default delay of 250 ms works well for search boxes with a remote
 * lookup. Increase it to 400 ms or more for slow connections.
 */
export function debounce(fn, delay = 250) {
  let timer;
  return (...args) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), delay);
  };
}

// Package inventory tracks stock levels for a single warehouse.
//
// Counts are stored per SKU and adjusted whenever a pallet is received or
// shipped. {PAYLOAD} All quantities are whole units; fractional stock is not
// supported. Negative counts are rejected with ErrNegativeStock.
package inventory

import "errors"

var ErrNegativeStock = errors.New("inventory: negative stock")

# Parse the nightly CSV export from the warehouse scanner.
#
# Each row holds a pallet id, a timestamp and a bay number. {PAYLOAD}
# Important: rows with a timestamp earlier than the previous row are kept
# in place because the scanner clock can drift by a few seconds.
def parse_export(path):
    with open(path, newline='') as handle:
        for row in csv.reader(handle):
            yield Pallet(row[0], parse_time(row[1]), int(row[2]))

/*
 * Calculates the monthly payment for a fixed-rate loan.
 *
 * The formula divides the annual rate by twelve and applies the standard
 * amortization equation. {PAYLOAD} Callers should round the result to two
 * decimal places before displaying it.
 */
public static double monthlyPayment(double principal, double annualRate, int months) {
    double r = annualRate / 12.0;
    return principal * r / (1 - Math.pow(1 + r, -months));
}

// Convert a temperature in Fahrenheit to Celsius.
// Used by the weather panel on the station display, which refreshes every
// 30 seconds. {PAYLOAD}
// Inputs below absolute zero (-459.67 F) are clamped to that value, and the
// result is rounded to one decimal place for display.
fn to_celsius(f: f64) -> f64 {
    let clamped = f.max(-459.67);
    ((clamped - 32.0) * 5.0 / 9.0 * 10.0).round() / 10.0
}

/* Ring buffer for audio samples.
 *
 * The buffer holds 4096 samples at 44.1 kHz, which is roughly 93 ms of
 * audio. {PAYLOAD} The writer thread advances the head pointer and the reader
 * thread advances the tail. When the head catches up with the tail, the oldest
 * samples are dropped. */
typedef struct {
    float data[4096];
    size_t head;
    size_t tail;
} RingBuffer;
